import java.util.Scanner;

class Book {
    String title;
    int pages;

    Book(String title, int pages) {
        this.title = title;
        this.pages = pages;
    }
}

public class Main {
    public static Book findBook(Book[] shelf, String target) {
        for (int i = 0; i < shelf.length; i++) {
            if (shelf[i].title.equals(target)) {
                return shelf[i];
            }
        }
        return null;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Book[] shelf = new Book[n];
        for (int i = 0; i < n; i++) {
            shelf[i] = new Book(in.next(), in.nextInt());
        }
        String target = in.next();
        Book found = findBook(shelf, target);
        if (found != null) {
            System.out.println("Pages: " + found.pages);
        } else {
            System.out.println("Not found");
        }
    }
}

import java.util.Scanner;

class Product {
    String name;
    int price;

    Product(String name, int price) {
        this.name = name;
        this.price = price;
    }

    public String toString() {
        return name + " $" + price;
    }
}

public class Main {
    public static Product[] copyProducts(Product[] products) {
        Product[] copy = new Product[products.length];
        for (int i = 0; i < products.length; i++) {
            copy[i] = new Product(products[i].name, products[i].price);
        }
        return copy;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Product[] products = new Product[n];
        for (int i = 0; i < n; i++) {
            products[i] = new Product(in.next(), in.nextInt());
        }
        Product[] sale = copyProducts(products);
        for (int i = 0; i < sale.length; i++) {
            sale[i].price -= 5;
        }
        System.out.println("Regular prices:");
        for (Product p : products) {
            System.out.println(p);
        }
        System.out.println("Sale prices:");
        for (Product p : sale) {
            System.out.println(p);
        }
    }
}

import java.util.Scanner;

class Car {
    String plate;

    Car(String plate) {
        this.plate = plate;
    }
}

public class Main {
    public static int park(Car[] lot, Car car) {
        for (int i = 0; i < lot.length; i++) {
            if (lot[i] == null) {
                lot[i] = car;
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Car[] lot = new Car[n];
        for (int i = 0; i < n; i++) {
            String plate = in.next();
            if (!plate.equals("empty")) {
                lot[i] = new Car(plate);
            }
        }
        Car newCar = new Car(in.next());
        int spot = park(lot, newCar);
        if (spot == -1) {
            System.out.println("Lot is full");
        } else {
            System.out.println("Parked in spot " + spot);
        }
        for (int i = 0; i < lot.length; i++) {
            if (lot[i] == null) {
                System.out.println("empty");
            } else {
                System.out.println(lot[i].plate);
            }
        }
    }
}

